'use strict'

const { strictEqual } = require('node:assert')

const { Query: PostgresQuery } = require('./query.js')

function Postgres () {
  strictEqual(typeof PostgresQuery, 'function')

  const options = {
    database: 'postgres',
    host: ['localhost'],
    port: [5432],
    user: 'postgres',
  }

  function handler (query) {
    return query
  }

  function dispatch (query) {
    function handler (query) {
      return query
    }

    return handler(query)
  }

  return [handler(new PostgresQuery()), dispatch(new PostgresQuery())]
}

module.exports = Postgres
